58	// Applies f to all in-edges of vertices where f.cond(v) is true.
59	// Uses dense iteration (iterates over all vertices).
60	// When should_output(fl), allocates and returns next vertex subset.
61	template <class data, class vertex, class VS, class F>
62	vertexSubsetData<data> edgeMapDense(graph<vertex> GA, VS& vertexSubset, F &f, const flags fl) {
63	  using D = tuple<bool, data>;
64	  long n = GA.n;
65	  vertex *G = GA.V;
66	  if (should_output(fl)) {
67	    D* next = newA(D, n);
68	    auto g = get_emdense_gen<data>(next);
69	    parallel_for (long v=0; v<n; v++) {
70	      std::get<0>(next[v]) = 0;
71	      if (f.cond(v)) {
72	        G[v].decodeInNghBreakEarly(v, vertexSubset, f, g, fl & dense_parallel);
73	      }
74	    }
75	    return vertexSubsetData<data>(n, next);
76	  } else {
77	    auto g = get_emdense_nooutput_gen<data>();
78	    parallel_for (long v=0; v<n; v++) {
79	      if (f.cond(v)) {
80	        G[v].decodeInNghBreakEarly(v, vertexSubset, f, g, fl & dense_parallel);
81	      }
82	    }
83	    return vertexSubsetData<data>(n);
84	  }
85	}
