#include "ligra.h"

//Bellman-Ford relaxation. A vertex d joins the next frontier iff this round
//lowered its tentative distance; Visited[] makes sure d is added at most once
//per round even when several in-edges improve it.
struct BF_F {
  intE* ShortestPathLen;
  int* Visited;
  BF_F(intE* _ShortestPathLen, int* _Visited) :
    ShortestPathLen(_ShortestPathLen), Visited(_Visited) {}
  inline bool update (uintE s, uintE d, intE edgeLen) { //Update ShortestPathLen if found a better path
    intE newDist = ShortestPathLen[s] + edgeLen;
    if(ShortestPathLen[d] > newDist) {
      ShortestPathLen[d] = newDist;
      if(Visited[d] == 0) { Visited[d] = 1; return 1; } //first improvement this round
    }
    return 0;
  }
  inline bool updateAtomic (uintE s, uintE d, intE edgeLen){ //atomic version of Update
    intE newDist = ShortestPathLen[s] + edgeLen;
    return (writeMin(&ShortestPathLen[d],newDist) &&
	    CAS(&Visited[d],0,1));
  }
  //cond function is always true: any vertex may still be improved
  inline bool cond (uintE d) { return cond_true(d); }
};

//vertex map function to reset Visited before the next round of relaxations
struct BF_Vertex_F {
  int* Visited;
  BF_Vertex_F(int* _Visited) : Visited(_Visited) {}
  inline bool operator() (uintE i){
    Visited[i] = 0;
    return 1;
  }
};

template <class vertex>
void Compute(graph<vertex>& GA, commandLine P) {
  long start = P.getOptionLongValue("-r",0);
  long n = GA.n;
  //initialize ShortestPathLen to "infinity", except for the source
  intE* ShortestPathLen = newA(intE,n);
  {parallel_for(long i=0;i<n;i++) ShortestPathLen[i] = INT_E_MAX;}
  ShortestPathLen[start] = 0;

  int* Visited = newA(int,n);
  {parallel_for(long i=0;i<n;i++) Visited[i] = 0;}

  vertexSubset Frontier(n,start); //initial frontier contains only the source

  long round = 0;
  bool negativeCycle = false;
  while(!Frontier.isEmpty()){
    if(round == n) {
      //a simple shortest path uses at most n-1 edges, so still making
      //progress after n rounds means some reachable cycle has negative weight
      negativeCycle = true;
      break;
    }
    //relax all out-edges of the frontier; dense_forward avoids the (useless)
    //dense in-edge scan since cond is always true
    vertexSubset output = edgeMap(GA, Frontier, BF_F(ShortestPathLen,Visited), GA.m/20, dense_forward);
    vertexMap(output,BF_Vertex_F(Visited)); //clear Visited for the next round
    Frontier.del();
    Frontier = output; //set new frontier
    round++;
  }
  Frontier.del();

  if(negativeCycle) cout << "BellmanFord negative weight cycle" << endl;

  //count the vertices reachable from the source and total up their distances
  long reachable = 0, sum = 0;
  for(long i=0;i<n;i++) {
    if(ShortestPathLen[i] != INT_E_MAX) { reachable++; sum += ShortestPathLen[i]; }
  }
  cout << "BellmanFord rounds: " << round << endl;
  cout << "BellmanFord reachable: " << reachable << endl;
  cout << "BellmanFord sum: " << sum << endl;

  free(Visited); free(ShortestPathLen);
}

